  const tShieldEnd = 120;

  // Professional easings
  const easeOutCubic = Easing.bezier(0.33, 1, 0.68, 1);
  // Subtle spring/overshoot for the shield reveal and text slide
  const springOut = Easing.bezier(0.175, 0.885, 0.32, 1.15);

